const filteredUsers = [];

const botPatterns = [
  /_bot_/i,
  /^bot-/i,
  /-bot$/i,
  /^gitlab-/i,
  /-token$/i,
  /token-/i,
  /^project_\d+_bot_/,
  /^group_\d+_bot_/
];

const serviceUsernames = [
  'ghost',
  'root',
  'alert-bot',
  'support-bot',
  'sonarqube',
  'gitlab-support'
];

const serviceNameKeywords = [
  'token',
  'bot',
  'service account',
  'service',
  'CI/CD',
  'GitLab',
  'Alert',
  'Support',
  'SonarQube',
  'API'
];

for (const item of items) {
  const user = item.json;

  const isBotUsername = botPatterns.some(pattern => pattern.test(user.username)) ||
                       serviceUsernames.includes(user.username);

  const isBotName = serviceNameKeywords.some(keyword => 
    user.name && user.name.toLowerCase().includes(keyword.toLowerCase())
  );

  const isBotEmail = user.email && (
    user.email.includes('noreply') ||
    user.email.includes('no-reply') ||
    user.email.includes('bot@') ||
    user.email.includes('service@')
  );

  const isRealUser = !isBotUsername && !isBotName && !isBotEmail;

  if (isRealUser) {
    filteredUsers.push({
      json: {
        ...user,
        is_bot: false
      }
    });
  } else {
    console.log(`Filtrado bot/service: ${user.username} (${user.name})`);
  }
}

console.log(`Usuarios totales: ${items.length}, Usuarios reales: ${filteredUsers.length}`);
return filteredUsers;

const processedProjects = [];

for (const item of items) {
  const project = item.json;

  const namespace = project.namespace || {};
  const owner = project.owner || {};

  processedProjects.push({
    json: {
      gitlab_id: project.id,
      name: project.name,
      name_with_namespace: project.name_with_namespace,
      description: project.description || '',
      path: project.path,
      path_with_namespace: project.path_with_namespace,
      web_url: project.web_url,
      ssh_url: project.ssh_url_to_repo,
      http_url: project.http_url_to_repo,
      default_branch: project.default_branch || 'main',
      visibility: project.visibility,
      owner_id: owner.id || null,
      namespace_id: namespace.id || null,
      namespace_name: namespace.name || null,
      last_activity_at: project.last_activity_at,
      created_at_gitlab: project.created_at,
      updated_at_gitlab: project.updated_at,
      archived: project.archived || false,
      forks_count: project.forks_count || 0,
      star_count: project.star_count || 0,
      open_issues_count: project.open_issues_count || 0,
      creator_id: project.creator_id || null,
      commit_count: project.statistics?.commit_count || 0,
      storage_size: project.statistics?.storage_size || 0,
      repository_size: project.statistics?.repository_size || 0,
      processed_at: new Date().toISOString(),
      _debug: false
    }
  });
}

console.log(`Procesados ${processedProjects.length} proyectos`);
return processedProjects;

const relations = [];

const accessLevelMap = {
  10: 'Guest',
  20: 'Reporter',
  30: 'Developer',
  40: 'Maintainer',
  50: 'Owner'
};

let projectsProcessed = 0;
let totalMembers = 0;

for (const item of items) {
  projectsProcessed++;

  const project = item.context?.project || item.json.project || {};
  const members = Array.isArray(item.json) ? item.json : [];

  totalMembers += members.length;

  for (const member of members) {
    if (!member.id || !project.gitlab_id) {
      console.warn('Miembro o proyecto sin ID:', { member, project });
      continue;
    }

    const accessLevel = member.access_level || 30;
    const role = accessLevelMap[accessLevel] || 'Unknown';
    const membershipType = accessLevel >= 40 ? 'owner' : 'collaborator';

    relations.push({
      json: {
        user_gitlab_id: member.id,
        project_gitlab_id: project.gitlab_id,
        username: member.username,
        user_name: member.name,
        project_name: project.name,
        project_path_with_namespace: project.path_with_namespace || project.name,
        access_level: accessLevel,
        user_role: role,
        membership_type: membershipType,
        notification_level: member.notification_level || 3,
        expires_at: member.expires_at || null,
        created_at_gitlab: member.created_at || new Date().toISOString(),
        last_activity_at: project.last_activity_at || new Date().toISOString(),
        is_direct_member: true,
        sync_timestamp: new Date().toISOString(),
        _debug: false
      }
    });
  }
}

console.log(`\n=== RESUMEN DE RELACIONES ===\nProyectos procesados: ${projectsProcessed}\nMiembros totales: ${totalMembers}\nRelaciones creadas: ${relations.length}\n`);

return relations;

const commitRequests = [];

const cutoffDate = new Date();
cutoffDate.setDate(cutoffDate.getDate() - 90);

let activeProjects = 0;
let inactiveProjects = 0;

for (const item of items) {
  const project = item.json;

  const lastActivity = project.last_activity_at ? new Date(project.last_activity_at) : null;
  const isActive = lastActivity && lastActivity > cutoffDate;

  if (isActive) {
    activeProjects++;

    const endDate = new Date();
    const startDate = new Date();
    startDate.setDate(startDate.getDate() - 30);

    commitRequests.push({
      json: {
        projectId: project.gitlab_id,
        projectName: project.name,
        since: startDate.toISOString().split('T')[0],
        until: endDate.toISOString().split('T')[0],
        per_page: 100,
        with_stats: true,
        project_data: {
          name: project.name,
          path_with_namespace: project.path_with_namespace,
          last_activity_at: project.last_activity_at
        },
        _request_timestamp: new Date().toISOString(),
        _days_back: 30
      }
    });
  } else {
    inactiveProjects++;
  }
}

console.log(`\n=== SOLICITUDES DE COMMITS ===\nProyectos totales: ${items.length}\nProyectos activos (últimos 90 días): ${activeProjects}\nProyectos inactivos: ${inactiveProjects}\nSolicitudes generadas: ${commitRequests.length}\n`);

return commitRequests;

const processedCommits = [];
let totalCommits = 0;
let commitsWithStats = 0;
for (const item of items) {
  const commits = Array.isArray(item.json) ? item.json : [];
  const projectId = item.json?.projectId || item.context?.projectId;
  const projectName = item.json?.projectName || 'Unknown Project';
  totalCommits += commits.length;
  for (const commit of commits) {
    const commitDate = new Date(commit.created_at || commit.committed_date || commit.authored_date);
    const stats = commit.stats || {};
    const hasStats = stats.total !== undefined;
    if (hasStats) commitsWithStats++;

    processedCommits.push({
      json: {
        gitlab_id: commit.id,
        project_gitlab_id: projectId,
        project_name: projectName,
        title: commit.title || '',
        message: commit.message || '',
        author_name: commit.author_name || '',
        author_email: commit.author_email || '',
        committer_name: commit.committer_name || '',
        committer_email: commit.committer_email || '',
        created_at_gitlab: commit.created_at,
        committed_date: commit.committed_date,
        web_url: commit.web_url || '',
        stats_additions: stats.additions || 0,
        stats_deletions: stats.deletions || 0,
        stats_total: stats.total || 0,
        commit_date: commitDate.toISOString().split('T')[0],
        commit_hour: commitDate.getHours(),
        commit_weekday: commitDate.getDay(),
        commit_month: commitDate.getMonth() + 1,
        commit_year: commitDate.getFullYear(),
        is_merge_commit: commit.parent_ids && commit.parent_ids.length > 1,
        parent_ids: commit.parent_ids || [],
        processed_at: new Date().toISOString(),
        _has_stats: hasStats
      }
    });
  }
}
 /*
console.log(`\\n=== PROCESAMIENTO DE COMMITS ===\\nCommits totales: ${totalCommits}\\nCommits con estadísticas: ${commitsWithStats}\\nCommits procesados: ${processedCommits.length}\\n`);
*/

return processedCommits;

const hourlyMetrics = {};

let commitsProcessed = 0;

for (const item of items) {
  const commit = item.json;

  if (!commit.author_email || !commit.commit_date || commit.commit_hour === undefined) {
    continue;
  }

  commitsProcessed++;

  const userEmail = commit.author_email;
  const date = commit.commit_date;
  const hour = commit.commit_hour;
  const key = `${userEmail}-${date}-${hour}`;

  if (!hourlyMetrics[key]) {
    hourlyMetrics[key] = {
      author_email: userEmail,
      metric_date: date,
      metric_hour: hour,
      commit_count: 0,
      additions_total: 0,
      deletions_total: 0,
      files_changed_total: 0,
      commit_ids: [],
      first_commit_time: null,
      last_commit_time: null
    };
  }

  const metric = hourlyMetrics[key];
  metric.commit_count += 1;
  metric.additions_total += commit.stats_additions || 0;
  metric.deletions_total += commit.stats_deletions || 0;
  metric.files_changed_total += 1;
  metric.commit_ids.push(commit.gitlab_id);

  const commitTime = new Date(commit.created_at_gitlab || commit.processed_at);
  if (!metric.first_commit_time || commitTime < new Date(metric.first_commit_time)) {
    metric.first_commit_time = commitTime.toISOString();
  }
  if (!metric.last_commit_time || commitTime > new Date(metric.last_commit_time)) {
    metric.last_commit_time = commitTime.toISOString();
  }
}

const result = [];
for (const key in hourlyMetrics) {
  const metric = hourlyMetrics[key];

  const avgChangesPerCommit = metric.commit_count > 0 
    ? (metric.additions_total + metric.deletions_total) / metric.commit_count 
    : 0;
  const isWorkingHour = metric.metric_hour >= 9 && metric.metric_hour <= 17;

  const date = new Date(metric.metric_date);
  const weekday = date.getDay();
  const isWeekday = weekday >= 1 && weekday <= 5;

  result.push({
    json: {
      author_email: metric.author_email,
      metric_date: metric.metric_date,
      metric_hour: metric.metric_hour,
      commit_count: metric.commit_count,
      additions_total: metric.additions_total,
      deletions_total: metric.deletions_total,
      files_changed_total: metric.files_changed_total,
      avg_changes_per_commit: parseFloat(avgChangesPerCommit.toFixed(2)),
      first_commit_time: metric.first_commit_time,
      last_commit_time: metric.last_commit_time,
      is_working_hours: isWorkingHour,
      is_weekday: isWeekday,
      sync_timestamp: new Date().toISOString()
    }
  });
}

console.log(`\\n=== MÉTRICAS HORARIAS ===\\nCommits procesados: ${commitsProcessed}\\nMétricas generadas: ${result.length}\\n`);

return result;
